"""Lease-scoped discovery, causal application evidence and frozen requests."""
from common import addresses
from ledger import Ledger
from protocols import signature


def discovery(live, leases, at, low):
    buckets = {}
    for name, lease in leases.items():
        active = lease['start'] <= at < lease['end']
        buckets[name] = {'state': 'usable' if active else 'inactive',
                         'alias': False, 'internal': {}, 'external': {},
                         'conflicts': set(), 'unresolved': set()}
    for kind, row in live:
        if kind != 'icmp':
            continue
        bucket = buckets[row.lease]
        if bucket['state'] == 'inactive':
            continue
        if row.probe.endswith('/c'):
            if row.result == 'echo' and row.responder == row.target:
                bucket['alias'] = True
            continue
        if row.result == 'timeout':
            continue
        if row.responder != row.target:
            witnesses = bucket['external']
        elif row.result == 'echo':
            witnesses = bucket['internal']
        else:
            continue  # A self error is not discovery evidence.
        old = witnesses.get(row.responder)
        if old is None or row.event < old:
            witnesses[row.responder] = row.event
    for name, bucket in buckets.items():
        if bucket['state'] == 'inactive':
            continue
        bucket['conflicts'] = bucket['internal'].keys() & bucket['external'].keys()
        if bucket['alias']:
            bucket['state'] = 'alias'
        elif bucket['conflicts']:
            bucket['state'] = 'conflict'
        if bucket['state'] != 'usable':
            bucket['internal'] = {}
            bucket['external'] = {}
        bucket['unresolved'] = low[name] - bucket['internal'].keys() - bucket['external'].keys()
    return buckets


def build(context, records, low):
    snapshots = []
    active = {name: False for name in context['requests']}
    requests_at = {q: [] for q in context['queries']}
    for name, row in context['requests'].items():
        requests_at[row['at']].append((name, row))
    ledger = Ledger(records)
    # Wire parsing depends on kind and payload alone. Memoizing also avoids
    # reparsing the same exchange in multiple revisions, identities or queries.
    wire_cache = {}
    for at in context['queries']:
        counts, live = ledger.at(at)
        buckets = discovery(live, context['leases'], at, low)
        latest = {}
        unbound = 0
        for kind, row in live:
            if kind != 'app':
                continue
            bucket = buckets[row.lease]
            witness = bucket['internal'].get(row.target)
            if witness is None:
                witness = bucket['external'].get(row.target)
            if bucket['state'] != 'usable' or witness is None or witness > row.event:
                unbound += 1
                continue
            key = (row.lease, row.target, row.service)
            previous = latest.get(key)
            if previous is None or row.attempt > previous[0]:
                latest[key] = (row.attempt, [row])
            elif row.attempt == previous[0]:
                previous[1].append(row)

        # Each set is a known open/closed subset; absence means unknown.
        service_sets = {(lease, service): [set(), set(), set(), set(), 0]
                        for lease in context['leases'] for service in context['services']}
        statuses = {}
        for (lease, target, service), (attempt, rows) in latest.items():
            values = service_sets[lease, service]
            all_closed = True
            all_open = True
            agreed = None
            for row in rows:
                if row.result != 'closed':
                    all_closed = False
                if row.result != 'open':
                    all_open = False
                    continue
                key = (context['services'][service], row.payload)
                if key not in wire_cache:
                    wire_cache[key] = signature(*key)
                parsed = wire_cache[key]
                if parsed is None:
                    values[4] += 1
                    all_open = False
                elif agreed is None:
                    agreed = parsed
                elif agreed != parsed:
                    all_open = False
            if all_closed:
                state = 'closed'
            elif all_open:
                state = 'open'
            else:
                state = 'unknown'
            statuses[lease, target, service] = state
            if state != 'unknown':
                offset = 0 if target in buckets[lease]['internal'] else 2
                values[offset + (state == 'closed')].add(target)

        for name, row in requests_at[at]:
            active[name] = (row['address'] in buckets[row['lease']]['internal']
                            and statuses.get((row['lease'], row['address'], row['service']), 'unknown') == 'unknown')

        reports = []
        for lease in sorted(context['leases']):
            bucket = buckets[lease]
            services = []
            for service in sorted(context['services']):
                io, ic, eo, ec, errors = service_sets[lease, service]
                internal_only = io if bucket['external'] and ec == bucket['external'].keys() else set()
                services.append({'id': service, 'internal_open': addresses(io),
                                 'internal_closed': addresses(ic), 'external_open': addresses(eo),
                                 'external_closed': addresses(ec), 'internal_only': addresses(internal_only),
                                 'protocol_errors': errors})
            reports.append({'lease': lease, 'state': bucket['state'],
                            'conflicts': addresses(bucket['conflicts']),
                            'internal': addresses(bucket['internal']), 'external': addresses(bucket['external']),
                            'unresolved': addresses(bucket['unresolved']), 'services': services})
        snapshots.append({'at': at, 'ledger': counts, 'unbound_applications': unbound, 'leases': reports})
    return snapshots, active
