"""Strict, offline ADB and length-prefixed plist exchange adapters."""
import io
import plistlib
import struct

CNXN = 0x4e584e43
AUTH = 0x48545541
CLSE = 0x45534c43


def checksum(data):
    return sum(data) & 0xffffffff


def packet(command, arg0, arg1, body):
    return struct.pack('<6I', command, arg0, arg1, len(body),
                       checksum(body), command ^ 0xffffffff) + body


def send_connect():
    return packet(CNXN, 0x01000000, 4096, b'host::zgrab2')


def send_close():
    return packet(CLSE, 0, 0, b'')


def read_adb_response(data):
    if len(data) < 24:
        raise ValueError('short ADB header')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:24])
    if (command not in (CNXN, AUTH) or command ^ magic != 0xffffffff
            or length > 65535 or len(data) != 24 + length):
        raise ValueError('bad ADB framing')
    body = data[24:]
    if checksum(body) != check:
        raise ValueError('bad ADB checksum')
    if command == CNXN:
        banner = body.decode('utf-8', errors='strict')
        version = f'{(arg0 >> 16) & 255}.{(arg0 >> 8) & 255}.{arg0 & 255}'
        return ('CNXN', version, banner)
    return ('AUTH', arg0, arg1, body)


GET_VERSION = 0
GET_PRODUCT_NAME = 1
USBMUXD_COMMANDS = {
    GET_VERSION: ('ProductVersion', 'GetValue'),
    GET_PRODUCT_NAME: ('ProductName', 'GetValue')}


def get_value_request(kind):
    key, request = USBMUXD_COMMANDS[kind]
    body = plistlib.dumps({'Key': key, 'Label': 'usbmuxd', 'ProtocolVersion': '2',
                          'Request': request}, fmt=plistlib.FMT_XML, sort_keys=False)
    return struct.pack('>I', len(body)) + body


def get_plists(stream, kind):
    header = stream.read(4)
    if len(header) != 4:
        raise ValueError('short plist header')
    size = struct.unpack('>I', header)[0]
    if not 1 <= size <= 65532:
        raise ValueError('invalid plist length')
    body = stream.read(size)
    if len(body) != size:
        raise ValueError('short plist frame')
    value = plistlib.loads(body)
    expected = USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value) != {'Key', 'Request', 'Value'}
            or value['Key'] != expected or value['Request'] != 'GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream = io.BytesIO(data)
    version = get_plists(stream, GET_VERSION)
    product = get_plists(stream, GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync', version, product)


def signature(kind, data):
    try:
        if kind == 'tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind == 'adb':
            return read_adb_response(data)
        if kind == 'sync':
            return send_messages(data)
        raise ValueError('unknown protocol')
    except Exception:
        # plistlib exposes several parser-specific exception types, including
        # recursion, index and struct errors for malformed binary plists. All
        # parsing failures are bad wire evidence, not rejected logical rows.
        return None


def probe_script(kind):
    import base64
    def encode(data):
        return base64.b64encode(data).decode('ascii')
    if kind == 'tcp':
        return [], []
    if kind == 'adb':
        return [encode(send_connect())], [encode(send_close())]
    return [encode(get_value_request(GET_VERSION)), encode(get_value_request(GET_PRODUCT_NAME))], []
